<template><div class="sf-segments" :class="{'sf-segments--pills':appearance==='pills'}" role="tablist" :aria-label="label"><button v-for="(item,index) in items" :key="item.value" type="button" role="tab" :id="id+'-'+index" :aria-selected="value===item.value?'true':'false'" :aria-controls="item.panelId||null" :tabindex="tabIndex(item)" :disabled="disabled||item.disabled" @click="select(item)" @keydown="navigate($event,index)">{{ item.label }}</button></div></template>
<script>
let sequence=0
export default {name:'SfSegmentedControl',props:{items:{type:Array,required:true},value:[String,Number],label:{type:String,required:true},disabled:Boolean,appearance:{type:String,default:'pills'}},data(){return {id:'sf-segments-'+(++sequence)}},methods:{tabIndex(item){const selected=this.items.find(i=>!i.disabled&&i.value===this.value)||this.items.find(i=>!i.disabled);return selected===item?0:-1},select(item){if(!this.disabled&&!item.disabled){this.$emit('input',item.value);this.$emit('change',item.value)}},navigate(event,index){if(this.disabled||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const enabled=this.items.map((item,i)=>({item,i})).filter(e=>!e.item.disabled);if(!enabled.length)return;const current=enabled.findIndex(e=>e.i===index),direction=event.key==='ArrowRight'?1:-1;const next=event.key==='Home'?enabled[0]:event.key==='End'?enabled[enabled.length-1]:enabled[(current+direction+enabled.length)%enabled.length];this.select(next.item);this.$nextTick(()=>this.$el.querySelectorAll('button')[next.i].focus())}}}
</script>
